import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const AddResident = () => {
  const [resident, setResident] = useState({
    name: '',
    roomId: '',
    inOutStatus: 'In',
  });
  const [rooms, setRooms] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    fetchRooms();
  }, []);

  const fetchRooms = async () => {
    try {
      const response = await axios.get('http://localhost:5001/api/rooms');
      setRooms(response.data);
    } catch (err) {
      console.error(err);
    }
  };

  const handleChange = (e) => {
    setResident({ ...resident, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:5001/api/residents', resident);
      navigate('/residents');
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>Add Resident</h2>
      <input
        type="text"
        name="name"
        placeholder="Resident Name"
        value={resident.name}
        onChange={handleChange}
        required
      />
      <select name="roomId" value={resident.roomId} onChange={handleChange} required>
        <option value="">Select Room</option>
        {rooms.map((room) => (
          <option key={room._id} value={room._id}>
            {room.roomNumber}
          </option>
        ))}
      </select>
      <select name="inOutStatus" value={resident.inOutStatus} onChange={handleChange}>
        <option value="In">In</option>
        <option value="Out">Out</option>
      </select>
      <button type="submit" className="submit-btn">
        Add Resident
      </button>
    </form>
  );
};

export default AddResident;
